func (q *Queries) UpsertShelfItem(ctx context.Context, arg UpsertShelfItemParams) (LibraryShelfItem, error) {
	row := q.db.QueryRow(ctx, upsertShelfItem, arg.UserID, arg.BookID, arg.Shelf)
	var i LibraryShelfItem
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.BookID,
		&i.Shelf,
		&i.CreatedAt,
	)
	return i, err
}
